   "summary": "财政部、央行、金融监管总局优化财政金融协同促内需政策，个人消费贷与信用卡分期累计贴息上限由每年3000元提高至5000元，贴息范围扩至汽车/装修等专项分期、消费分期、预借现金分期，年贴息比例1%。六大行系统已自动适配，前期签约客户无需重签。",
   "decision": "招联消费贷可直接对接贴息红利，优化自营/助贷定价与签前话术；同时警惕以'贴息'为名的非持牌中介诈骗，严格渠道合规。",
