   "summary": "《银行保险机构资产管理产品信息披露管理办法》施行，理财业绩比较基准改为挂钩债券指数/存款利率的公式化披露，不得随意调整；央行、市场监管总局公告明确正在流通的人民币禁止买卖和囤积炒作，'豹子号''生日钞'直播间高价叫卖属违规，仅停流通旧版币与纪念币可合规收藏。",
