   "summary": "晚点LatePost深度调查指出，独立AI应用同时面对'产品被模型吞掉、增长不带来利润、用户入口在谁手里'三难题，Kuse、Cursor等案例显示推理成本随增长上升、部分产品毛利为负，创业者转向卖交付、自训模型或绑定客户业务深处求生。",
