   "summary": "财政部近期下达2026年育儿补贴补助资金999亿元，较上年增10.6%，预计全年各级财政共安排约1100亿元；从2025年1月1日起无论一二三孩每年领3600元至满3周岁，免征个税，线上经全国统一系统或支付宝/微信入口申领。",
   "decision": "建宝女儿'开心'8/25出生，每年可领3600元/孩，应在出生当年或次年首申、之后连续两年续领，是家庭现金流的确定性增量，务必按时申领。",
