   "summary": "2026年贵州省托育消费补贴活动时间为7月13日至12月31日，3岁以下婴幼儿可领，按单笔实付订单50%补贴、单张消费券最高抵扣1000元，每名婴幼儿限领1张、20个自然日内有效，通过'多彩宝'APP申领、云闪付支付。",
   "decision": "开心未来入托可享该补贴，建宝可提前了解户籍地与常住地政策，做好托育费用规划。",
