   "summary": "长治市医保局等四部门《关于调整完善生育保险政策的通知》9月1日起实施，将参加职工医保的灵活就业人员纳入生育保险（费率0.5%、与职工医保合并缴纳），产前检查设置统一服务包、住院生育医疗100%支付，且新生儿同期合规费用一并纳入结算，生育津贴10个工作日内直发。",
   "decision": "妻刘镜预产期临近（8/25），留意灵活就业生育保险参保与新生儿落地参保流程，提前备好妊娠登记材料。",
