   "summary": "《国家基本药物目录(2026版)》9月1日施行，总数增至794种，新增116种。重点提高儿童用药可及性：新增5种儿童专用药，26种药物补充儿童剂型，着力解决'用药靠掰、用量靠猜'；同时将结核病用药扩至26种实现全覆盖。公立医疗机构须优先配备。",
