   "summary": "规划提出到2030年规上中小企业人均营业收入累计增长15%左右，专精特新'小巨人'企业达2.2万家、国家级特色产业集群600个；加强上市培育、建设债券'科技板'、设立国家中小企业发展基金二期，防范化解拖欠账款长效机制基本建立。",
