   "summary": "8月28日住建部、自然资源部、金融监管总局联合完善商品住房销售制度；央行、金融监管总局改革完善房地产信贷管理；证监会出台资本市场支持房地产发展新模式意见。新政从销售、信贷到资本融资整体重构，推进现房销售、房贷最长期限延至40年。",
