   "summary": "8月31日教育部等七部门发布特殊教育发展提升'十五五'行动计划，提出到2030年适龄残疾儿童义务教育入学率巩固在97%以上，健全特殊教育资源体系，推进普惠融合发展。",
   "decision": "普惠教育政策延续，关注地方配套对育儿家庭（含'开心'）公共服务供给的长期影响。",
