   "summary": "国家网信办、工信部、公安部、交通运输部、商务部、央行、海关总署、税务总局、市场监管总局、金融监管总局十部门联合公布《促进和规范电子单证应用规定》，自9月1日起施行，统一电子单证格式与系统接口，支撑跨境贸易与供应链数字化。",
