   "summary": "9月起多项新规落地：《住房公积金管理条例》修订9月20日施行，提取付房租不再设收入比例门槛；首个客服协同国标要求企业对智能客服回复内容负责；9/30施行的《金融产品网络营销管理办法》禁用'低门槛''秒到账''低利率'等话术；微短剧须对AI生成内容添加标识。",
