   "summary": "《国务院关于修改〈住房公积金管理条例〉的决定》9月20日施行。提取住房公积金支付房租不再设置房租超过家庭工资收入规定比例的门槛；新增装修自住住房、支付自住住房物业费、国务院批准的其他住房消费情形等提取情形；贷款审查时限由15日缩短为10日。",
