   "summary": "据国家电影局数据，2026年暑期档电影票房124.98亿元，观影人次3.4亿，分别同比增长4.45%、5.86%，国产影片票房占比71.71%。票房前三均为国产片：《功夫女足》23.15亿元、《欢迎来龙餐馆》19.51亿元、《八仙！》18.46亿元；放映场次3851万场创历史新高。",
