   "summary": "灯塔分析师陈晋指出，今年暑期档有三个积极信号：平均票价下降、上座率提升、营业影城数持续增长，说明增长靠更多人走进影院撑起，是健康扎实的增长；男性与35岁以上观众占比提升，市场结构优化。",
